#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    string s = to_string(n);
    long long l = s.length(), ans = 1, pro = 1;

    if (l == 1) {
        cout << n << '\n';
        return 0;
    }

    for (long long i = 0; i < l; i++) {
        ans *= (s[i] - '0');
    }

    pro = max(pro, ans);

    for (long long i = 0; i < l; i++) {
        ans = 1;

        for (long long j = 0; j < i; j++) {
            if (s[j] - '0' != 0) {
                ans *= (s[j] - '0');
            }
        }

        if ((s[i] - '0') - 1 != 0) {
            ans *= (s[i] - '0') - 1;
        }

        for (long long j = i + 1; j < l; j++) {
            ans *= 9;
        }

        pro = max(pro, ans);
    }

    cout << pro << '\n';
    return 0;
}

