#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;

    string s = to_string(n);
    long long ans = 1;

    for (char c : s)
        ans *= c - '0';

    long long best = ans;

    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '0')
            continue;

        long long product = 1;

        for (size_t j = 0; j < i; ++j)
            product *= s[j] - '0';

        product *= s[i] - '0' - 1;

        for (size_t j = i + 1; j < s.size(); ++j)
            product *= 9;

        best = max(best, product);
    }

    cout << best << '\n';
    return 0;
}

